mcv.addEventListener('click',e=>{const r=mcv.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;let best=null,bd=34;for(const d of SECTOR_DEFS){const[sx,sy]=mapXY(d,r.width,r.height),dd=hyp(sx-x,sy-y);if(dd<bd){bd=dd;best=d.id}}if(best){mapSel=best;drawMap();renderMapSide()}});
function fmtT(t){const m=Math.floor(t/60),s=Math.floor(t%60);return`${m}:${String(s).padStart(2,'0')}`}
// the Brood's road to a win, at a glance: one cell per system it holds, against the 7 it must hold for WIN_TIME
function broodMeter(b){const col=b>=6?'var(--danger)':b>=5?'var(--amber)':sideCol('brood');let cells='';for(let i=0;i<VIC_NEED;i++)cells+=`<i style="display:inline-block;width:14px;height:8px;margin-right:3px;background:${i<b?col:'rgba(255,255,255,.1)'}"></i>`;
  return`<div style="margin-top:8px"><div class="note" style="margin:0 0 4px">Brood threat · ${Math.min(b,VIC_NEED)} of ${VIC_NEED}${b>=VIC_NEED&&S.victory&&S.victory.side==='brood'?` · galaxy falls in ${fmtT(Math.max(0,WIN_TIME-(S.T-S.victory.since)))}`:''}</div>${cells}<div class="note" style="margin:4px 0 0">The Brood wins only by holding ${VIC_NEED} systems for ${Math.round(WIN_TIME/60)} minutes; it can't win on the deadline.</div></div>`}
// the keys that matter right now, under the prompt: what this hull can do with this target in this moment (at most six)
function keysNow(){const P=S.player,p=W&&W.player;if(!p||P.docked||W.bridge||W.gunseat||W.dead||touchUI())return[];const k=[],T=W.tgt&&validTgt(W.tgt)?W.tgt:null;
  if(blHull(P.cls)){const set=(S.sectors[W.sid].charges||[]).filter(ch=>ch.o===blKey(P)).length;if(T&&(T.kind==='ast'||T.kind==='wpt'))k.push([kb('mine'),'charge']);if(set)k.push([kb('det'),`detonate ${set}`],[kb('cancel'),'cancel']);if(p.mining)k.push([kb('mine'),'hold to scoop'])}
  if(isScoutCls(P.cls)&&!P.limpetUsed&&limpetTarget())k.push([kb('mine'),'hold: limpet']);
  if(T&&T.kind==='ship'&&hostile('player',T.ref.side)){if(W.lock&&W.lock.locked&&P.rack>0)k.push([kb('msl'),'missile']);if((P.swarm||0)>0&&swarmCap(P))k.push([kb('swarm'),'swarm']);k.push([kb('track'),'hold to track'])}
  if(W.missiles.some(m=>m.tgt===p&&m.kind!=='swarm'))k.unshift([kb('flare'),'flares']);
  if(T&&(T.kind==='gate'||T.kind==='station'||T.kind==='ast'||T.kind==='outpost'))k.push([kb('autopilot'),'autopilot']);
  if(p.hull<p.st.hull*.35)k.push([kb('distress'),'distress']);
  if(!T)k.push([kb('tgtH'),'nearest hostile'],[kb('cycle'),'cycle targets']);
  return k.slice(0,6)}
function keysNowRender(){const el=$('hKeysNow');if(!el)return;const h=keysNow().map(([key,t])=>`<span><kbd>${esc(key)}</kbd>${esc(t)}</span>`).join('');if(el.innerHTML!==h)el.innerHTML=h}
